// «Мое_город»: фотографические текстуры для эпохи «Бель-эпок» и булыжной мостовой (с 1.2.0).
// Источник — Poly Haven (poly­haven.com), лицензия CC0 (общественное достояние, указывать автора не обязательно):
//   стены: Sandstone Blocks 04 (штукатурка), Large Red Bricks (кирпич), Sandstone Blocks 05 (камень);
//   крыши: Grey Roof Tiles (шифер, цинк), Clay Roof Tiles 02 (черепица); мостовая: Cobblestone Floor 08.
// Картинки уменьшены до 256×256 (кирпич и камень — 512×512) и вшиты в файл как data:-адреса (так работает и из папки, без интернета, и без «грязного» холста).
// Стены, шифер и черепица — серые «карты яркости»: игра накладывает их на цвет здания, поэтому палитра эпохи не меняется.
// PHOTO.img[имя] — готовые картинки; PHOTO.ready — обещание: все загружены (или прошло 6 секунд — тогда игра рисует по-старому).
(function () {
  'use strict';
  var SRC = {
 "plaster": "data:image/jpeg;base64,",
 "brick": "data:image/jpeg;base64,",
 "stone": "data:image/jpeg;base64,",
 "slate": "data:image/jpeg;base64,",
 "tile": "data:image/jpeg;base64,",
 "cobble": "data:image/jpeg;base64,"
};
  var P = window.PHOTO = { img: {}, ready: null };
  var names = Object.keys(SRC), left = names.length;
  P.ready = new Promise(function (res) {
    var done = false; function fin() { if (!done) { done = true; res(); } }
    setTimeout(fin, 6000);
    names.forEach(function (k) {
      var im = new Image();
      im.onload = function () { P.img[k] = im; if (--left <= 0) fin(); };
      im.onerror = function () { if (--left <= 0) fin(); };
      im.src = SRC[k];
    });
  });
})();
